    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(v, default=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def get_int(o, *keys, default=0):
        for k in keys:
            try:
                if k in o:
                    v = o.get(k)
                    if isinstance(v, int):
                        return v
                    if isinstance(v, float):
                        return int(v)
            except:
                pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def nearest(items, s):
        best = None
        best_d = None
        for it in items:
            p = pos(it)
            if p is None:
                continue
            d = manhattan(p, s)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(items, s):
        best = None
        best_d = None
        for it in items:
            p = pos(it)
            if p is None:
                continue
            d = manhattan(p, s)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    def step_toward(s, t):
        return [clamp_step(t[0] - s[0]), clamp_step(t[1] - s[1])]

    def step_away(s, t):
        return [clamp_step(s[0] - t[0]), clamp_step(s[1] - t[1])]

