    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        t = nearest(targets, s)
        if t is not None:
            return step_toward(s, t)
        own = observation.get("self_territory") or []
        t = farthest(own, o)
        if t is not None:
            return step_toward(s, t)
        return step_toward(s, o)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("food") or []
    if resources:
